"use client";
import {useState} from "react";
import {MessageSquareText,Check} from "lucide-react";
import {ContextFileInput} from "@/components/context-file-input";
export function CompanyProfileAssistant({onDraft}:{onDraft:(fields:Record<string,string>)=>void}) {
 const[text,setText]=useState(""),[question,setQuestion]=useState(""),[draft,setDraft]=useState<Record<string,string>|null>(null),[error,setError]=useState(""),[busy,setBusy]=useState(false);
 async function prepare(){setBusy(true);setError("");setDraft(null);try{const response=await fetch("/api/company/profile-draft",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({contribution:text})});const result=await response.json();if(!response.ok)throw new Error(result.error);setDraft(Object.fromEntries(result.proposals.map((p:{field:string;value:string})=>[p.field,p.value])));setQuestion(result.question);}catch(e){setError(e instanceof Error?e.message:"Fielded could not prepare an update.");}finally{setBusy(false);}}
 return <details className="company-document"><summary><MessageSquareText size={18}/>Build the profile with Fielded</summary><div className="stack-form"><label>What should Fielded know?<textarea value={text} onChange={e=>setText(e.target.value)} maxLength={12000} rows={4}/></label><ContextFileInput purpose="company" disabled={busy} onExtract={(content,name)=>{if(content.length>12000){setError("Use a shorter excerpt, up to 12,000 characters.");return;}setText(`Source: ${name}\n${content}`.slice(0,12000));}}/><button type="button" className="button button-quiet" disabled={busy||text.trim().length<5} onClick={()=>void prepare()}>{busy?"Preparing suggestions...":"Suggest profile updates"}</button>{error&&<p role="alert" className="form-message">{error}</p>}{draft&&<><dl>{Object.entries(draft).map(([field,value])=><div key={field}><dt>{field}</dt><dd style={{whiteSpace:"pre-wrap"}}>{value}</dd></div>)}</dl>{question&&<p>{question}</p>}{!!Object.keys(draft).length&&<button type="button" className="button button-quiet" onClick={()=>{onDraft(draft);setDraft(null);}}><Check size={16}/>Use these changes in the form</button>}<p className="role-note">Nothing is saved until you review the profile and select Save company profile.</p></>}</div></details>;
}
